// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address coll, address debt) public {
        vm.assume(coll != debt);
        vm.assume(uint160(coll) > 0);

        // Clone-form calldata: 4-byte selector, then immutable args
        // (junk filler at 0..0x14, collateral bytes at 0x14..0x28,
        // debt bytes at 0x28..0x3c), then 2-byte little immargs length 0x3c.
        bytes memory cd = abi.encodePacked(
            c.collateral.selector,
            new bytes(0x14),
            bytes20(coll),
            bytes20(debt),
            uint16(0x3c)
        );

        (bool ok, bytes memory ret) = address(c).call(cd);
        assertTrue(ok);

        address got = abi.decode(ret, (address));
        // Reference: collateral() reads immutable arg at offset 0x14 -> coll.
        assertTrue(got == coll);
    }
}
